package com.blog.exception;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { record ErrorResponse(Instant timestamp,int status,String message,String path){} @ExceptionHandler(ApiExceptions.ResourceNotFoundException.class) @ResponseStatus(HttpStatus.NOT_FOUND) ErrorResponse notFound(RuntimeException e,HttpServletRequest r){return error(404,e,r);} @ExceptionHandler({ApiExceptions.UnauthorizedException.class,org.springframework.security.access.AccessDeniedException.class}) @ResponseStatus(HttpStatus.FORBIDDEN) ErrorResponse forbidden(Exception e,HttpServletRequest r){return error(403,e,r);} @ExceptionHandler({ApiExceptions.BadRequestException.class,ApiExceptions.EmailAlreadyExistsException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) ErrorResponse bad(RuntimeException e,HttpServletRequest r){return error(400,e,r);} @ExceptionHandler(MethodArgumentNotValidException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) ErrorResponse validation(MethodArgumentNotValidException e,HttpServletRequest r){return error(400,new RuntimeException(e.getBindingResult().getFieldErrors().getFirst().getDefaultMessage()),r);} @ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) ErrorResponse other(Exception e,HttpServletRequest r){return error(500,new RuntimeException("Unexpected server error"),r);} private ErrorResponse error(int s,Exception e,HttpServletRequest r){return new ErrorResponse(Instant.now(),s,e.getMessage(),r.getRequestURI());} }
